namespace Meteo.Core.Geo;

/// <summary>
/// Static surface description on the fine (1 km) grid, generated by tools/Meteo.GeoPrep and embedded in the DLL:
/// mean elevation, mean terrain normal (for sun incidence on slopes) and land-cover derived albedo and
/// "thermal efficiency" (relative share of absorbed energy that becomes sensible heat).
/// </summary>
public sealed class SurfaceData
{
    private const int Magic = 0x544D5331; // "TMS1"

    public required GridDefinition Grid { get; init; }
    /// <summary>Mean elevation (m AMSL).</summary>
    public required float[] Elevation { get; init; }
    /// <summary>Mean unit terrain normal: east, north, up components (≈ map x, y; grid convergence &lt; 3° neglected).</summary>
    public required float[] NormalE { get; init; }
    public required float[] NormalN { get; init; }
    public required float[] NormalU { get; init; }
    /// <summary>Broadband surface albedo (0..1) from land cover.</summary>
    public required float[] Albedo { get; init; }
    /// <summary>Thermal efficiency (0 = water, ~0.6 forest, 1 = cropland, &gt;1 bare rock / built-up).</summary>
    public required float[] Efficiency { get; init; }
    /// <summary>Fraction of water (0..1).</summary>
    public required float[] Water { get; init; }

    public void Write(Stream s)
    {
        using var bw = new BinaryWriter(s, System.Text.Encoding.UTF8, leaveOpen: true);
        bw.Write(Magic);
        bw.Write(Grid.X0); bw.Write(Grid.Y0); bw.Write(Grid.CellSize); bw.Write(Grid.Nx); bw.Write(Grid.Ny);
        foreach (var a in new[] { Elevation, NormalE, NormalN, NormalU, Albedo, Efficiency, Water })
            foreach (var v in a) bw.Write(v);
    }

    public static SurfaceData Read(Stream s)
    {
        using var br = new BinaryReader(s, System.Text.Encoding.UTF8, leaveOpen: true);
        if (br.ReadInt32() != Magic) throw new InvalidDataException("Not a Meteo surface file.");
        var g = new GridDefinition(br.ReadDouble(), br.ReadDouble(), br.ReadDouble(), br.ReadInt32(), br.ReadInt32());
        int n = g.Nx * g.Ny;
        float[] Arr() { var a = new float[n]; for (int i = 0; i < n; i++) a[i] = br.ReadSingle(); return a; }
        return new SurfaceData
        {
            Grid = g, Elevation = Arr(), NormalE = Arr(), NormalN = Arr(), NormalU = Arr(),
            Albedo = Arr(), Efficiency = Arr(), Water = Arr(),
        };
    }

    private static readonly Lazy<SurfaceData> Embedded = new(() =>
    {
        var asm = typeof(SurfaceData).Assembly;
        var name = asm.GetManifestResourceNames().FirstOrDefault(n => n.EndsWith("surface_1km.bin", StringComparison.OrdinalIgnoreCase))
            ?? throw new InvalidOperationException("Embedded resource surface_1km.bin not found. Run tools/Meteo.GeoPrep.");
        using var s = asm.GetManifestResourceStream(name)!;
        return Read(s);
    });

    /// <summary>Surface data embedded in the assembly.</summary>
    public static SurfaceData Default => Embedded.Value;

    /// <summary>
    /// ESA WorldCover classes → (albedo, thermal efficiency). Heuristic values from literature ranges:
    /// forests absorb a lot but evaporate (low Bowen ratio); fields, rocks and towns heat the air best; water not at all.
    /// </summary>
    public static (float Albedo, float Efficiency) LandCoverProperties(int worldCoverClass) => worldCoverClass switch
    {
        10 => (0.12f, 0.60f), // tree cover
        20 => (0.18f, 0.80f), // shrubland
        30 => (0.20f, 0.90f), // grassland
        40 => (0.20f, 1.00f), // cropland
        50 => (0.15f, 1.10f), // built-up
        60 => (0.25f, 1.20f), // bare / sparse vegetation, rock
        70 => (0.70f, 0.10f), // snow and ice
        80 => (0.07f, 0.00f), // permanent water
        90 => (0.15f, 0.40f), // herbaceous wetland
        95 => (0.12f, 0.40f), // mangroves
        100 => (0.20f, 0.80f), // moss and lichen
        _ => (0.18f, 0.85f),
    };
}
